interface.signature:
interface CodeSnippet {
  id: string;
  title: string;
  description: string;
  language: 'javascript' | 'python' | 'java' | 'cpp' | 'html' | 'css' | 'typescript' | string;
  difficulty: 'beginner' | 'intermediate' | 'advanced';
  category: string;
  code: string;
  lineCount: number;
  characterCount: number;
  specialChars: string[];
  createdAt: Timestamp;
}

interface UserCodeProgress {
  userId: string;
  snippetId: string;
  language: string;
  wpmAchieved: number;
  accuracyAchieved: number;
  completionDate?: Timestamp;
  attempts: number;
  bestWpm: number;
  bestAccuracy: number;
  languageProficiency: {
    [language: string]: {
      totalSnippets: number;
      completedSnippets: number;
      averageWpm: number;
      averageAccuracy: number;
    };
  };
}

interface CodeModeProps extends TypingAreaProps {
  language: string;
  syntaxHighlighting: boolean;
  codeMode: true;
  onLanguageChange: (language: string) => void;
  specialCharEmphasis: boolean;
}
